        this.m = m;
        this.k = k;
    }

    public void addElement(int num) {
        q.addLast(num);
        if (q.size() > m) q.removeFirst();
    }

    public int calculateMKAverage() {
        if (q.size() < m) return -1;
        List<Integer> s = new ArrayList<>(q);
        Collections.sort(s);
        long sum = 0;
        for (int i = k; i < m - k; i++) sum += s.get(i);
        return (int) (sum / (m - 2 * k));
    }
