from collections import deque


class MKAverage:

    def __init__(self, m, k):
        self.m, self.k = m, k
        self.N = 100000
        self.cnt = [0] * (self.N + 1)
        self.sm = [0] * (self.N + 1)
        self.q = deque()

    def _add(self, v, dc, ds):
        i = v
        while i <= self.N:
            self.cnt[i] += dc
            self.sm[i] += ds
            i += i & -i

    def _pref(self, v):
        c = s = 0
        i = v
        while i > 0:
            c += self.cnt[i]
            s += self.sm[i]
            i -= i & -i
        return c, s

    def _sum_k_smallest(self, k):
        pos = c = s = 0
        pw = 1 << 17
        while pw:
            nxt = pos + pw
            if nxt <= self.N and c + self.cnt[nxt] < k:
                pos = nxt
                c += self.cnt[nxt]
                s += self.sm[nxt]
            pw >>= 1
        cf, sf = self._pref(pos + 1)
        return sf - (cf - k) * (pos + 1)

    def addElement(self, num):
        self.q.append(num)
        self._add(num, 1, num)
        if len(self.q) > self.m:
            old = self.q.popleft()
            self._add(old, -1, -old)

    def calculateMKAverage(self):
        if len(self.q) < self.m:
            return -1
        hi = self._sum_k_smallest(self.m - self.k)
        lo = self._sum_k_smallest(self.k)
        return (hi - lo) // (self.m - 2 * self.k)

