class MKAverage {
public:
    MKAverage(int m, int k) : m(m), k(k), N(100000), cnt(N + 1, 0), sm(N + 1, 0) {}

    void addElement(int num) {
        q.push_back(num);
        add(num, 1, num);
        if ((int)q.size() > m) {
            add(q.front(), -1, -q.front());
            q.pop_front();
        }
    }

    int calculateMKAverage() {
        if ((int)q.size() < m) return -1;
        long long hi = sumKSmallest(m - k);
        long long lo = sumKSmallest(k);
        return (int)((hi - lo) / (m - 2 * k));
    }

private:
    int m, k, N;
    vector<long long> cnt, sm;
    deque<int> q;

    void add(int v, int dc, long long ds) {
        for (int i = v; i <= N; i += i & (-i)) {
            cnt[i] += dc;
            sm[i] += ds;
        }
    }

    pair<long long, long long> pref(int v) {
        long long c = 0, s = 0;
        for (int i = v; i > 0; i -= i & (-i)) {
            c += cnt[i];
            s += sm[i];
        }
        return {c, s};
    }

    long long sumKSmallest(int kk) {
        int pos = 0;
        for (int pw = 1 << 17; pw > 0; pw >>= 1)
            if (pos + pw <= N && cnt[pos + pw] + countBelow(pos) < kk)
                pos += pw;
        int v = pos + 1;
        auto [c, s] = pref(v);
        return s - (c - kk) * v;
    }

    long long countBelow(int pos) {
        long long c = 0;
        for (int i = pos; i > 0; i -= i & (-i)) c += cnt[i];
        return c;
    }
};

