class MKAverage {
    private final int m, k;
    private static final int N = 100000;
    private final long[] cnt = new long[N + 1];
    private final long[] sm = new long[N + 1];
    private final Deque<Integer> q = new ArrayDeque<>();

    public MKAverage(int m, int k) {
        this.m = m;
        this.k = k;
    }

    public void addElement(int num) {
        q.addLast(num);
        add(num, 1, num);
        if (q.size() > m) {
            int old = q.removeFirst();
            add(old, -1, -old);
        }
    }

    public int calculateMKAverage() {
        if (q.size() < m) return -1;
        long hi = sumKSmallest(m - k);
        long lo = sumKSmallest(k);
        return (int) ((hi - lo) / (m - 2 * k));
    }

    private void add(int v, int dc, long ds) {
        for (int i = v; i <= N; i += i & (-i)) {
            cnt[i] += dc;
            sm[i] += ds;
        }
    }

    private long[] pref(int v) {
        long c = 0, s = 0;
        for (int i = v; i > 0; i -= i & (-i)) {
            c += cnt[i];
            s += sm[i];
        }
        return new long[]{c, s};
    }

    private long sumKSmallest(int kk) {
        int pos = 0;
        for (int pw = 1 << 17; pw > 0; pw >>= 1) {
            int nxt = pos + pw;
            if (nxt <= N && cnt[nxt] + countBelow(pos) < kk) pos = nxt;
        }
        long[] p = pref(pos + 1);
        return p[1] - (p[0] - kk) * (pos + 1);
    }

    private long countBelow(int pos) {
        long c = 0;
        for (int i = pos; i > 0; i -= i & (-i)) c += cnt[i];
        return c;
    }
}

